package dao;import model.*;import java.sql.*;import java.util.*;import java.math.*;
public class TicketDAO5 extends DAO5{public TicketDAO5(Connection c){super(c);}public Ticket5[] getBookedTickets(Screening5 s)throws Exception{List<Ticket5>a=query(Ticket5.class,"SELECT * FROM tblTicket5 WHERE tblScreening5id=? AND TrangThai='DA_PHAT_HANH'",s.getId());Map<Integer,Seat5> seats=new HashMap<>();for(Seat5 g:new SeatDAO5(con).getSeats(s))seats.put(g.getId(),g);try(PreparedStatement p=stmt("SELECT id,tblSeat5id FROM tblTicket5 WHERE tblScreening5id=? AND TrangThai='DA_PHAT_HANH'",s.getId());ResultSet r=p.executeQuery()){Map<Integer,Integer>ids=new HashMap<>();while(r.next())ids.put(r.getInt(1),r.getInt(2));for(Ticket5 t:a){t.setSuatChieu(s);t.setGhe(seats.get(ids.get(t.getId())));}}return a.toArray(new Ticket5[0]);}
public Ticket5[] prepareTickets(Screening5 s,Seat5[] selected)throws Exception{Screening5 fresh=new ScreeningDAO5(con).get(s.getId());if(!"MO_BAN".equals(fresh.getTrangThai())||!fresh.getGioBatDau().isAfter(java.time.LocalDateTime.now()))throw new IllegalArgumentException("Suất chiếu đã đóng");Map<Integer,Seat5> valid=new HashMap<>();for(Seat5 g:new SeatDAO5(con).getSeats(s))valid.put(g.getId(),g);Set<Integer> booked=new HashSet<>();for(Ticket5 t:getBookedTickets(s))booked.add(t.getGhe().getId());Set<Integer> used=new HashSet<>();List<Ticket5> out=new ArrayList<>();if(selected.length==0)throw new IllegalArgumentException("Chọn ít nhất một ghế");for(Seat5 g:selected){if(!valid.containsKey(g.getId())||booked.contains(g.getId())||!used.add(g.getId()))throw new IllegalArgumentException("Ghế không hợp lệ hoặc đã được đặt");g=valid.get(g.getId());Ticket5 t=new Ticket5();t.setGhe(g);t.setSuatChieu(fresh);t.setGia(new BigDecimal("VIP".equals(g.getLoaiGhe())?"75000":"50000"));t.setTrangThai("TAM");out.add(t);}return out.toArray(new Ticket5[0]);}
public Ticket5[] issueTickets(Order5 o)throws Exception{if(!"DA_THANH_TOAN".equals(o.getTrangThai()))throw new IllegalStateException("Đơn chưa thanh toán");for(Ticket5 t:o.getVe()){t.setMaVe("V"+UUID.randomUUID().toString().replace("-", "").substring(0,20));t.setTrangThai("DA_PHAT_HANH");t.setId(insert("INSERT INTO tblTicket5(MaVe,Gia,TrangThai,tblOrder5id,tblScreening5id,tblSeat5id) VALUES(?,?,?,?,?,?)",t.getMaVe(),t.getGia(),t.getTrangThai(),o.getId(),t.getSuatChieu().getId(),t.getGhe().getId()));}return o.getVe();}}
